<?php
declare(strict_types=1);require_once __DIR__.'/includes/bootstrap.php';require_once __DIR__.'/includes/presentation.php';
if(($_SERVER['REQUEST_METHOD']??'GET')!=='POST')pv_redirect('login.php');if(!pv_verify_csrf())pv_redirect('login.php?error=expired');$username=trim((string)($_POST['username']??''));$password=(string)($_POST['password']??'');$ip=substr((string)($_SERVER['REMOTE_ADDR']??''),0,64);
try{
    $db=pv_db();$now=time();
    $stmt=$db->prepare('SELECT attempts,time FROM login_trys WHERE ip=? LIMIT 1');if($stmt){$stmt->bind_param('s',$ip);$stmt->execute();$try=$stmt->get_result()->fetch_assoc();$stmt->close();if($try&&(int)$try['attempts']>=6&&$now-(int)$try['time']<300)pv_redirect('login.php?error=throttled');}
    $stmt=$db->prepare('SELECT m.*,COALESCE(o.tamer,m.created_avatar,1) tamer,COALESCE(o.memonmap,m.memonmap,1) memonmap FROM members m LEFT JOIN members_options o ON o.id=m.id WHERE m.username=? LIMIT 1');if(!$stmt)throw new RuntimeException('auth');$stmt->bind_param('s',$username);$stmt->execute();$row=$stmt->get_result()->fetch_assoc();$stmt->close();
    if($row&&(int)$row['banned']!==0&&dn_world_expire_ban($db,(int)$row['id']))$row['banned']=0;
    $isBot=false;if($row&&pv_table_exists('nxt_bots')){$botCheck=$db->prepare('SELECT owner_id FROM nxt_bots WHERE owner_id=?');$botCheck->bind_param('i',$row['id']);$botCheck->execute();$isBot=(bool)$botCheck->get_result()->fetch_row();$botCheck->close();}
    if(!$row||$isBot||!pv_password_matches($password,(string)$row['password'])||(int)$row['banned']!==0){$stmt=$db->prepare('INSERT INTO login_trys(ip,username,time,attempts) VALUES(?,?,?,1) ON DUPLICATE KEY UPDATE username=VALUES(username),attempts=IF(VALUES(time)-time>300,1,attempts+1),time=VALUES(time)');if($stmt){$stmt->bind_param('ssi',$ip,$username,$now);$stmt->execute();$stmt->close();}dn_world_event('auth','login.failed','Sign-in rejected',['level'=>'warning']);usleep(250000);pv_redirect('login.php?error=invalid');}
    $maintenance=dn_world_maintenance($db);if(!empty($maintenance['enabled'])&&$row['role']!=='admin')dn_world_stop(503,'World maintenance',dn_world_clean((string)($maintenance['message']??'Please try again shortly.'),240));
    $stmt=$db->prepare('DELETE FROM login_trys WHERE ip=?');if($stmt){$stmt->bind_param('s',$ip);$stmt->execute();$stmt->close();}
    session_regenerate_id(true);$_SESSION['myid']=(int)$row['id'];$_SESSION['myuser']=(string)$row['username'];$_SESSION['session_version']=(int)($row['session_version']??0);dn_world_identity((int)$row['id'],(string)$row['username']);$_SESSION['map_preferences']=[0,(int)$row['memonmap'],nxt_skin_id((int)$row['tamer'])];$_SESSION['world_key']='cyberspace';$_SESSION['csrf_token']=bin2hex(random_bytes(32));$date=date('Y-m-d H:i:s');$uid=(int)$row['id'];$stmt=$db->prepare('UPDATE members SET llogin=?,last_login=?,ip=? WHERE id=?');$stmt->bind_param('issi',$now,$date,$ip,$uid);$stmt->execute();$stmt->close();$activity='Dashboard';$ua=substr((string)($_SERVER['HTTP_USER_AGENT']??''),0,250);$server=substr((string)($_SERVER['SERVER_NAME']??'local'),0,45);$stmt=$db->prepare('INSERT INTO online(id,username,activity,time,useragent,server) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE username=VALUES(username),activity=VALUES(activity),time=VALUES(time),useragent=VALUES(useragent),server=VALUES(server)');$stmt->bind_param('ississ',$uid,$row['username'],$activity,$now,$ua,$server);$stmt->execute();$stmt->close();dn_world_event('auth','login.success','Tamer signed in');pv_redirect('dashboard.php');
}catch(Throwable $e){pv_log('Login error: '.$e->getMessage());pv_redirect('login.php?error=service');}
